const j = $json || {};
if (j.claimAction !== 'acquire') throw new Error('[Claim] claimAction muss acquire oder release sein.');
if (!String(j.vorgangKey || '').trim()) throw new Error('[Claim] vorgangKey fehlt.');
if (!String(j.claimOwner || '').trim()) throw new Error('[Claim] claimOwner fehlt.');
if (!String(j.claimStage || '').trim()) throw new Error('[Claim] claimStage fehlt.');
const minutes = Math.max(1, Math.min(120, Number(j.leaseMinutes || 30)));
return { json: { ...j, leaseMinutes: minutes, claimAcquiredAt: $now.toISO(), claimExpiresAt: $now.plus({ minutes }).toISO() } };

if (items.length !== 1) throw new Error(`[Claim] Re-Read lieferte ${items.length} Zeilen.`);
const row = items[0].json || {};
const request = $('Validiere Claim-Anforderung').item.json;
const acquired = String(row.claim_owner || '') === String(request.claimOwner || '');
return [{ json: { ...row, claimAcquired: acquired, requestedClaimOwner: request.claimOwner } }];

